 return `${heading(b.trial?.kind==='mirror'?'鏡像いれーな':b.character==='irena'?({normal:'カイザー戦',ex:'EXカイザー戦',raid:'深淵レイド',god:'神域連戦'}[b.mode]||'カイザー戦'):'境界の戦い',`${b.test?'試験戦闘 / ':''}${b.trial?.kind==='mirror'?'黒鏡の聖堂':b.mode==='normal'?'通常攻略':{ex:'EXカイザー',raid:'深淵レイド',stella:'最終決戦・ステラ戦 / EXカイザー',final:'最終決戦・専用いれーな / EXカイザー',god:'神域連戦'}[b.mode]} / ${b.difficulty}`,(b.character==='irena'?'TURN ':'BATTLE / TURN ')+b.turn)}${!b.result?`<div class="combat-shortcuts" aria-label="戦闘画面の移動">${button('戦場へ','focusStage','','ghost')}${button('技を選ぶ ↓','focusCommands','','primary')}</div>`:''}<div class="battle-layout"><div><section ${b.trial?.kind==='mirror'?`style="--mirror-arena:url('${b.trial.unsealed?MIRROR_ART.beyond:MIRROR_ART.arena}')"`:''} ${b.campaign&&b.character==='irena'?`style="--campaign-background:url('${CAMPAIGN_ART.background}')"`:''} class="battle-stage ${b.trial?.kind==='mirror'?'mirror-stage'+(b.trial.awake?' mirror-awake':'')+(b.trial.unsealed?' mirror-unsealed':''):''} ${b.character==='irena'?'battle-portrait-cards':''} ${b.campaign&&b.character==='irena'?'campaign-stage':''} ${b.character==='final'?(b.balance===0?'stage-neutral':b.balance>0?'stage-divine':'stage-fallen'):b.character==='stella'?'stage-stella':''}"><div class="fighter fighter-player"><h3>${playerName}</h3><div class="portrait-frame"><img class="sprite portrait ${b.character==='irena'?'portrait-alpha':''}" src="${battlePortrait(b)}" alt="${playerName}の戦闘立ち絵"></div><div class="info"><div class="row between" style="gap:4px"><span>HP</span><span class="hpnum">${n(p.current)} / ${n(p.hp)}</span></div><div class="health player"><span class="hp-afterimage" style="transform:scaleX(${p.ratio})"></span><span class="hp-current" style="width:${p.ratio*100}%"></span></div><small>${b.character==='irena'?`致死耐性 ${b.lives} / 不屈 ${b.markLife}`:b.character==='stella'?`再誕 残り${3-b.rebirths}回`:`${b.balance>=0?'神化':'堕天'} 段階 ${stage(b.balance)}`}</small></div></div><div class="fighter fighter-enemy"><h3>${esc(enemyLabel(b))}</h3><div class="portrait-frame portrait-foe ${['ex','stella','final'].includes(b.mode)?'enemy-alpha':''} ${b.mode==='raid'?'raid-enemy':enemyImage(b)?'supplied-enemy':''}">${enemyArt(b)}</div><div class="info"><div class="row between" style="gap:4px"><span>HP</span><span class="hpnum">${n(b.enemy.hp)} / ${n(e.hp)}</span></div><div class="health"><span class="hp-afterimage" style="transform:scaleX(${hpPercent(b.enemy.hp,e.hp)/100})"></span><span class="hp-current" style="width:${hpPercent(b.enemy.hp,e.hp)}%"></span></div><small class="enemy-phase">第${b.enemy.phase}形態${' / 侵食 '+Math.round(b.erosion*100)+'%'}</small>${deadlineRemaining(b)!==null?`<span class="enemy-deadline" role="timer" aria-label="終末判定まで残り${deadlineRemaining(b)}ターン">終末判定 ${deadlineRemaining(b)}T</span>`:''}${b.campaign?`<small class="actual-enemy-state">${b.enemy.statuses.campaignArmor?'黒晶殻 ':''}${b.enemy.statuses.campaignSever?'権能の傷痕':''}${(b.tacticalB||b.lab20?.variant==='B')?(b.enemy.statuses.campaignArmor?' ／ 羽弾系×0.35':b.enemy.statuses.researchExposed?' ／ 殻解除・露出 '+b.enemy.statuses.researchExposed+'T（最終補正×1.6）':' ／ 殻なし'):''}</small>`:''}${b.trial?.kind==='mirror'?`<small class="actual-enemy-state mirror-state">${mirrorStateText(b)}</small>${mirrorStateDetails(b).length?`<details class="mirror-state-details"><summary>封印・状態の詳細</summary>${mirrorStateDetails(b).map(x=>`<span>${esc(x)}</span>`).join('')}</details>`:''}`:''}${b.trial?.kind==='guard-break'?`<small class="actual-enemy-state">${b.enemy.statuses.guardBreakArmor?'熾炎の鎧':''}</small>`:''}${b.trial?.kind==='three-phase'?`<small class="actual-enemy-state">${b.enemy.statuses.trialCrystal?'黒晶殻':''}${b.enemyStop?' ／ 震撼':''}</small>`:''}</div></div></section>${b.character==='irena'?`<section class="card battle-charge" style="padding:12px 18px;margin-top:12px"><div class="row between"><small>必殺ゲージ</small><span class="gold">${b.gauge}%</span></div><div class="gaugebar"><span style="width:${b.gauge}%"></span></div></section>`:b.character==='final'?`<section class="card" style="padding:12px 18px;margin-top:12px"><div class="row between"><small>堕天 −100</small><span class="gold">${b.balance>0?'+':''}${b.balance}</span><small>神化 ＋100</small></div><div class="balancebar"><i style="left:${(b.balance+100)/2}%"></i></div><div class="gauge-stages"><span class="${stage(b.balance)>=1?'reached':''}">I · 30</span><span class="${stage(b.balance)>=2?'reached':''}">II · 60</span><span class="${stage(b.balance)>=3?'reached':''}">III · 100</span></div></section>`:''}${b.result?resultView(a,b):`<div class="battle-controls ${b.character==='irena'?'irena-action-grid':''} ${b.character==='final'?'final-commands':''}" id="battle-actions" aria-label="戦闘コマンド">${skills.map(([id,title,desc,glyph])=>{const reason=available(b,id),clean=b.character==='final',blockLabel=clean?finalCommandLabel(b,id,reason):'',art=clean?MEDIA.fallenSkills[id]:null;return `<button class="skill ${['ultimate','genesis','ending','annihilate'].includes(id)?'ultimate':''} ${b.character==='irena'?'combat-action combat-action-'+id:''}" data-action="combat" data-id="${id}" ${reason?'disabled':''} aria-label="${esc(title)}" ${clean?'':`title="${esc(reason||(id==='guard'&&guardRulesText(b))||desc)}"`}><span class="glyph ${art?'has-art':''} ${b.character==='irena'?'combat-glyph combat-glyph-'+id:''}">${art?`<img class="skill-art" src="${art}" alt="" width="58" height="58">`:clean?uiIcon(({slash:'swords',guard:'shield',divine:'star',fallen:'crown',godspeed:'power',omnipotent:'crown',dominion:'star',annihilate:'gem',transcend:'shield',grasp:'target',genesis:'star',wait:'shield'})[id]||'gem',26):b.character==='irena'?combatIcon(id):glyph}</span><span class="combat-action-copy"><strong>${title}${!clean&&b.cd[id]>0?'　CT '+b.cd[id]:''}</strong>${clean?(blockLabel?`<small class="command-block-label">${esc(blockLabel)}</small>`:''):`<small>${reason||desc}</small>`}</span>${b.character==='irena'?'<span class="combat-chevron" aria-hidden="true">›</span>':''}</button>`;}).join('')}</div>`}</div><aside class="battle-aside stack"><section class="card ${b.character==='irena'?'combat-status-card':''}"><h3>${b.character==='irena'?'権能・自分の状態':'戦況と権能'}</h3>${b.difficulty!=='NORMAL'?`<span class="pill">${b.difficulty}</span>`:''}${b.character==='irena'?'<details class="battle-details"><summary>能力値を確認</summary>':''}${statsHTML(p)}<div class="small">敵：攻 ${n(e.atk)} / 防 ${n(e.def)} / 速 ${n(e.spd)}</div>${b.character==='irena'?'</details>':''}<div class="statuslist">${b.powers.map(id=>`<span class="pill">${name(id)}${['judge','judgewing','kingjudge','fallenjudge','abyssjudge'].includes(id)?' '+(b.stacks[id]||0)+'/2':''}</span>`).join('')}${b.buffs.map(x=>`<span class="pill gold">${FINAL_SKILLS[x.id]?.name||{divineMight:'神威',godlow:'堕天の神',grasp:'理外掌握',trialFocus:'蓄勢',guardBreakFocus:'蓄勢',campaignFocus:'蓄勢',mirrorFullRelease:'鏡界・完全解放'}[x.id]||x.id} ${x.remaining>900?'∞':x.remaining+'T'}</span>`).join('')}${Object.entries(b.statuses).map(([k,v])=>`<span class="pill">${{stun:'行動不能',seal:'封印',invulnerable:'無敵',pressure:'重圧',slow:'速度低下',fragile:'防御半減'}[k]||k} ${v}T</span>`).join('')}${b.ignoreDefense?`<span class="pill">崩壊 ${b.ignoreDefense}T</span>`:''}${b.noBuff?`<span class="pill">断絶 ${b.noBuff}T</span>`:''}${b.noPressure?`<span class="pill">重圧無効 ${b.noPressure}T</span>`:''}</div></section><section class="card ${b.character==='irena'?'combat-record':''}">${b.character==='irena'?`<p class="last-event" aria-live="polite">${esc(b.log.at(-1)||'戦闘を開始しました')}</p><details class="battle-log"><summary>戦闘記録を開く</summary>`:'<div class="row between" style="margin:0 0 12px"><h3>戦闘記録</h3><span class="tag">COMBAT LOG</span></div>'}<div class="log" aria-live="polite">${[...b.log].reverse().map(x=>`<p>${esc(x)}</p>`).join('')}</div>${b.character==='irena'?'</details>':''}</section>${!b.result?`<div class="compact-combat-tools">${button('能力・状態','combatInfo','','ghost')}${button('戦闘記録','combatLog','','ghost')}${button('撤退','askRetreat','','ghost')}</div>`:''}${!b.result?button('撤退する','askRetreat','','ghost combat-retreat'):''}</aside></div>`;
}
function resultView(a,b){if(b.trial?.kind==='mirror')return mirrorResult(b,button);if(b.lab20)return lab20Result(lab20Run,b,button);if(b.campaign&&!b.main20)return campaignResult(campaign,b,button);
 const victoryArt=b.result==='win'&&b.mode==='normal',r=b.reward||{},won=b.result==='win';
 const unlockNames={fallen:'権能「堕天」',king:'権能「堕天王」',judge:'権能「断罪」',star:'天星覇権 Lv.5',resonance:'権能共鳴',raid:'深淵レイド',mystery:'？？？？？ — 境界への扉',god:'神域連戦',final:'最終決戦専用いれーな'};
 const earned=!b.test&&won?`<div class="reward-grid" aria-label="今回の獲得報酬"><div><small>育成ポイント</small><strong data-reward="p">＋${n(r.p||0)}<em>P</em></strong>${r.bonusP?`<span data-reward="bonusP">初回報酬 ＋${n(r.bonusP)}P を含む</span>`:''}</div><div><small>各権能の欠片</small><strong data-reward="fragments">＋${n(r.fragments||0)}</strong></div><div><small>共鳴片</small><strong data-reward="resShards">＋${n(r.resShards||0)}</strong></div>${r.levels?`<div class="reward-growth"><small>基礎レベル</small><strong data-reward="levels">＋${n(r.levels)} Lv.</strong></div>`:''}${r.sp?`<div class="reward-growth"><small>ステータスポイント</small><strong data-reward="sp">＋${n(r.sp)}P</strong></div>`:''}</div>`:'';
 const discoveries=!b.test?`${r.unlocks?.length?`<div class="result-discoveries"><small>新たに取り戻した力</small>${r.unlocks.map(id=>`<strong data-unlock="${id}">✧ ${unlockNames[id]||esc(id)}</strong>`).join('')}</div>`:''}${r.achievements?.length?`<div class="result-achievements"><small>実績達成 · ${r.achievements.length}件</small>${r.achievements.map(id=>`<span data-achievement="${id}">${esc(ACHIEVEMENTS.find(x=>x.id===id)?.name||id)}</span>`).join('')}${button('実績の報酬を受け取る →','nav','archive','ghost')}</div>`:''}`:'';
 const report=battleReport(b);const recap=report.inputs?`<div class="result-recap" aria-label="今回の戦い"><span><strong>${report.inputs}</strong>行動</span><span><strong>${report.special}</strong>特殊攻撃</span><span><strong>${report.ultimate}</strong>必殺</span></div>`:'';
 const nextMilestone=won&&b.mode==='normal'&&!b.test?main20Milestones(a).find(([floor])=>!a.cleared.includes(floor)):null;
 return `<section class="result ${victoryArt?'result-illustrated':''}">${victoryArt?`<img class="result-art" src="${SCENES.victory}" alt="通常戦闘の勝利イラスト">`:''}<div class="result-content"><div class="tag">${b.test?'TEST RESULT':'BATTLE RESULT'}${b.difficulty!=='NORMAL'?` · ${esc(b.difficulty)}`:''}</div><h2>${won?'VICTORY':'DEFEAT'}</h2><p class="small">${b.test?'試験戦闘のため本編報酬・実績には反映しません。':won?'失われた力を、またひとつ取り戻した。':'育成を整え、技と装備を組み替えて再挑戦できます。'}${b.mode==='god'&&!won?'<br>今回の仮獲得素材と連戦進行を破棄しました。':''}</p>${recap}${earned}${discoveries}${nextMilestone?`<p class="result-next">次の節目：カイザー Lv.${nextMilestone[0]} 撃破で ${nextMilestone[1]}</p>`:''}${r.unlocks?.includes('mystery')?button('？？？？？ — 境界を越える','warp','','primary full'):''}<div class="row" style="justify-content:center">${button('聖域に戻る','finish','','ghost')}${button('育成・装備を整える','openupgrade','powers','ghost')}${button(won&&b.mode==='normal'&&b.floor<main20Limit(a)?'次の階層へ':b.mode==='god'&&a.gauntlet?'次の神へ':'再挑戦','retry','','primary')}</div></div></section>`;
}
function archive(a){return `${heading('戦いの記憶','全36実績で、天星覇権 Lv.5を取り戻す。','ARCHIVE / ACHIEVEMENTS')}<div class="notice">達成 ${a.achieved.length}/36 / 受取 ${a.claimed.length}件。各実績60Pは手動で1回受取。条件の原本は未回収のため、提供された復元一覧を採用しています。</div><div class="grid triple">${[['A','火力','与ダメージ1.05 / 1.09 / 1.12倍'],['B','技巧','特殊1.08 / 1.12 / 1.15倍、必殺最大1.12倍'],['C','均衡','HP1.05 / HP防1.07 / 全能力1.12倍＋被ダメ0.92倍']].map(([cat,title,text])=>{const rank=badgeRank(a,cat),count=ACHIEVEMENTS.filter(x=>x.cat===cat&&a.achieved.includes(x.id)).length;return `<section class="card"><div class="row between"><span class="badge">${{A:'⚔',B:'✧',C:'⬡'}[cat]}</span><span class="tag">${count} / 12</span></div><h3>${title}の徽章 ${['—','I','II','III'][rank]}</h3><p class="small">3 / 5 / 8個で自動進化。${text}</p><div class="row">${button(a.badge===cat?'装備解除':'装備する','badge',cat,'ghost',!rank)}</div></section>`;}).join('')}</div>${['A','B','C'].map(cat=>`<div class="section-head"><h2>${{A:'A — 火力',B:'B — 技巧',C:'C — 均衡'}[cat]}</h2><span class="tag">12 RECORDS</span></div><div class="grid">${ACHIEVEMENTS.filter(x=>x.cat===cat).map(x=>`<section class="card achievement ${a.achieved.includes(x.id)?'':'locked'}"><div class="emblem">${a.achieved.includes(x.id)?'✧':'◇'}</div><div><h3>${x.name}</h3><p>${a.route20===1&&/^A(6|7|8|9|10|11)$/.test(x.id)?x.detail.replace(/Lv\.(10|30|50|70|90|100)/g,(_,v)=>'第'+(Number(v)/5)+'階層'):x.detail}</p></div>${button(a.claimed.includes(x.id)?'受取済':a.achieved.includes(x.id)?'60P 受取':'未達成','claim',x.id,'',!a.achieved.includes(x.id)||a.claimed.includes(x.id))}</section>`).join('')}</div>`).join('')}`;}
function awakeningView(a){if(hasDivinity(a))return divinityView(a,button);return `${heading('失われた神格','新たな力ではない。かつての自分を、取り戻す。','DIVINE / REAWAKENING')}<div class="grid"><section class="card"><div class="tag">STAGE ${a.awakening} / 5</div><h2>${AWAKENINGS[a.awakening]}</h2><img class="awakening-art" src="${MEDIA.keyArt}" alt="ユーザー提供の共通キービジュアル（覚醒段階別ではありません）"><div class="levelsteps">${Array.from({length:5},(_,i)=>`<i class="${i<a.awakening?'on':''}"></i>`).join('')}</div><p class="small">各段階で通常基礎能力＋18%（補完）。共通キービジュアルを表示しています。5段階の専用絵とMP4は未提供です。</p></section><div class="stack"><section class="card"><h3>神格を取り戻す</h3><p class="small">共通神素材 ${a.godMaterials} / 神域の勲章 ${a.medals}<br>固有素材：${GODS.map((x,i)=>x+' '+a.godUnique[i]).join(' / ')}</p><p>${a.awakening<5?`次：${AWAKENINGS[a.awakening+1]}<br><span class="small">共通素材 ${(a.awakening+1)*5} ＋ ${GODS[a.awakening]}の固有素材1</span>`:'神格は完全に再生された。'}</p><div class="row">${button('手動で覚醒する','awaken','','primary',a.awakening>=5||a.godMaterials<(a.awakening+1)*5||a.godUnique[a.awakening]<1)}</div></section><section class="card"><h3>神域連戦</h3><p class="small">EX撃破後に解放。固定5連戦・各戦全回復。素材は全突破まで仮獲得。敗北・撤退で今回の進行と素材を失います。</p>${a.gauntlet?`<p>第${a.gauntlet.index+1}戦 / 仮素材 ${a.gauntlet.materials}</p>`:''}${godDifficultyControl(a)}<div class="row">${button(a.gauntlet?'連戦を続ける':'神域へ挑戦','fight','god','ghost',!a.flags.ex)}</div></section><section class="card"><h3>第5段階の演出基盤</h3><p class="small">専用MP4の再生に対応。現在は10秒のCSS代替演出を使用します。元の覚醒ムービーではありません。</p>${button('代替演出をプレビュー','movie','','ghost')}</section></div></div>`;}
function lab(a){return `${mirrorGate(button,sandbox?{...mirrorMemory,checkpoint:3}:mirrorMemory,sandbox?20:a.level)}${sandbox?'<div class="notice">全機能開放中：黒鏡の聖堂へ進むと第1→第2→第3形態を連続で戦えます。第3形態への直接挑戦も利用できます。鏡界の通常記録には反映されません。</div>':''}${heading('境界の実験場','本編の保存データから独立した、戦闘検証空間。','EXPERIMENT / SANDBOX')}<div class="notice">ここで始めた戦闘はすべて試験扱いです。報酬、実績、通常の解放フラグを更新しません。</div><section class="card stack"><h2>戦闘パラメータ</h2><div class="selectline"><label>モード<select id="labmode"><option value="normal">通常いれーな</option><option value="ex">EXカイザー</option><option value="three-phase">EXカイザー・三相決戦【試作】</option><option value="guard-break">熾竜・崩鎧試練【試作】</option><option value="stella">ステラ</option><option value="final">最終決戦いれーな</option></select></label><label>基礎攻撃倍率 <input id="labatk" type="number" value="1" min="0.1" max="20" step=".1"></label><label>基礎HP倍率 <input id="labhp" type="number" value="1" min="0.1" max="20" step=".1"></label></div><p class="small">全育成状態の試験キャラクターを使用。倍率はこの戦闘だけに適用します。三相決戦は黒翼＋堕天王の固定ビルドで開始。第二相から敵が硬化・重圧・回復を発動。破壊の権能・必殺で黒晶殻を解除、防御で重圧を解除、HP12%を回復して蓄勢を獲得。蓄勢は斬撃・破壊の権能を一回強化します。崩鎧試練は固定育成・刻印なしで開始。破壊の権能／必殺の命中で竜の鎧を解除、防御でHP12%回復と次の斬撃／権能の攻撃力3倍を獲得。鎧は実際の被弾3回で再形成されます。羽弾だけでは鎧を崩せません。数値は実験用です。</p>${button('独立試験を開始','labstart','','primary')}</section><div class="section-head"><h2>計算仕様</h2></div><section class="card"><p class="small">基本ダメージ = max(1, 攻撃×技倍率 − 防御×(1−無視率)) × 最終補正 ＋ 現在HP追加。最低保証は最後に適用。低HP倍率は排他的。深淵は基礎値から毎ターン6%の線形減少、下限5%。<br>堕天によるHP倍率は内部の生命割合を維持するため、倍率切替だけでは回復しません。羽弾と断罪の乗算・追加は別枠です。</p></section>`;}
